    "options": [
      "การไหลเวียนของน้ำและอากาศต้องไปจากส่วนสะอาดไปยังส่วนที่ไม่สะอาด",
      "การกำจัดของเสียให้เริ่มจากบริเวณสัตว์ป่วยแล้วไหลไปยังบริเวณสัตว์ปกติ",
      "ระบบน้ำต้องออกแบบไม่ให้น้ำเสียจากส่วนไม่สะอาดไหลย้อนเข้าสู่ส่วนสะอาด",
      "น้ำทิ้งจากโรงพักสัตว์ต้องไม่ไหลผ่านคอกสัตว์อื่นก่อนลงสู่ระบบบำบัดน้ำเสีย"
    ],
    "answer": 1,
    "explain": "หลักของทั้งโรงคือให้สิ่งที่สกปรกกว่าไหลออกไปหาสิ่งที่สกปรกกว่าเสมอ ของเสียจึงต้องเริ่มจากบริเวณสัตว์ปกติไปหาบริเวณสัตว์ป่วย ไม่ใช่ทิศทางกลับกัน เพราะการไหลจากสัตว์ป่วยมาหาสัตว์ดีคือการพาเชื้อไปให้สัตว์ที่ยังปกติ\n\n❌ ทำไมข้ออื่นผิด\n— น้ำและอากาศไหลจากส่วนสะอาดไปส่วนไม่สะอาด ซึ่งย้อนทิศกับทางเดินของซาก เป็นข้อกำหนดที่ถูกต้อง\n— การกันน้ำเสียจากส่วนไม่สะอาดไม่ให้ไหลย้อนเข้าส่วนสะอาดเป็นข้อกำหนดของระบบน้ำที่ถูกต้อง\n— การกำหนดให้น้ำทิ้งจากโรงพักสัตว์ไม่ผ่านคอกสัตว์อื่นก่อนลงระบบบำบัดเป็นข้อกำหนดที่ถูกต้อง",
    "source": "TJ p3; WRttiWQ7D9s [62:50]",
