    "answer": 2,
    "explain": "คุณภาพน้ำแยกดู 3 ด้าน ด้านกายภาพดูสี กลิ่น ความขุ่น ด้านเคมีดูเคมีทั่วไปกับโลหะหนัก และด้านชีวภาพคือต้องไม่พบเชื้อก่อโรค ไม่พบโคลิฟอร์มแบคทีเรียทั้งหมด และไม่พบ E. coli โดยน้ำที่สัมผัสเนื้อสัตว์ต้องมีคุณภาพไม่ต่ำกว่าน้ำประปาดื่มได้ที่กรมอนามัยกำหนด\n\n❌ ทำไมข้ออื่นผิด\n— กรดด่าง ความกระด้าง และโลหะหนัก เป็นเกณฑ์ด้านเคมี\n— สี กลิ่น ความขุ่น เป็นเกณฑ์ด้านกายภาพ ถึงจะเทียบกับเกณฑ์น้ำประปาดื่มได้ของกรมอนามัยก็ยังไม่ใช่ด้านชีวภาพ\n— คลอรีนตกค้าง ไนเตรต และสารแขวนลอย ยังเป็นการวัดทางเคมีและกายภาพ ไม่ใช่การนับจุลินทรีย์",
