    "explain": "ม.39 วางข้อห้ามฆ่าสัตว์นอกโรงฆ่าสัตว์ โดยยกเว้นให้เฉพาะท้องที่ที่ไม่มีโรงฆ่าสัตว์หรือมีเหตุผลพิเศษ เช่น พิธีกรรมทางศาสนา ซึ่งต้องมีการประกาศกำหนดสถานที่เป็นครั้งคราว ส่วน ม.40 ต่อด้วยข้อห้ามนำเนื้อสัตว์ออกจากบริเวณนั้นก่อนผ่านการตรวจ\n\n❌ ทำไมข้ออื่นผิด\n— ม.30 เป็นเรื่องคุณสมบัติและการแต่งตั้งพนักงานตรวจโรคสัตว์\n— ม.34 เป็นอำนาจสั่งงดฆ่าและแยกสัตว์ไว้ตรวจพิสูจน์ในขั้นตอนตรวจก่อนฆ่า และ ม.35 คือห้ามนำเนื้อสัตว์ออกจากโรงฆ่าก่อนได้รับการรับรองให้จำหน่าย\n— ม.42 เป็นเรื่องการชำระอากรการฆ่าสัตว์ ไม่ใช่ข้อห้ามฆ่านอกโรงฆ่าสัตว์",
