    "answer": 0,
    "explain": "การฆ่าในโรงฆ่าสัตว์ต้องมีหลักฐานการชำระอากรก่อนขนย้ายสัตว์เข้าฆ่า ส่วนการฆ่านอกโรงฆ่าสัตว์ไม่มีขั้นตอนนั้น จึงย้ายไปเก็บเป็นค่าธรรมเนียมในขั้นตอนการรับรองให้จำหน่ายแทน โดยยอดที่ผู้ประกอบการจ่ายเท่ากันทั้งสองทาง\n\n❌ ทำไมข้ออื่นผิด\n— ไม่มีการยกเว้นอากรให้การฆ่านอกโรงฆ่าสัตว์ เพียงแต่เปลี่ยนจังหวะการเก็บ\n— ไม่มีการคิดอัตราสองเท่า เพราะข้อกำหนดและการตรวจก่อนฆ่าและหลังฆ่ายังใช้เหมือนในโรงฆ่าสัตว์\n— การเก็บซ้ำทั้งสองขั้นตอนขัดกับหลักที่ว่าอัตราที่จ่ายจริงเท่ากันทั้งสองกรณี",
