    "explain": "ผลการตรวจซากหลังฆ่ามี 4 แบบ และเส้นแบ่งระหว่างการทำลายบางส่วนกับทั้งหมดคือขอบเขตของรอยโรค รอยโรคเฉพาะที่หรือ localized ให้ตัดส่วนนั้นทิ้งแล้วรับรองส่วนที่เหลือได้ แม้ซากจะถูกลดเกรด ส่วนรอยโรคที่กระจายทั่วซากหรือ generalized และกรณีมีสารตกค้าง ให้ทำลายทั้งหมด\n\n❌ ทำไมข้ออื่นผิด\n— ชนิดสัตว์ไม่ใช่เกณฑ์ตัดสิน แต่มีผลกับความหมายของคำว่าทำลายทั้งหมด ว่าหมายถึงทั้งซากหรือทั้งฝูงเท่านั้น\n— ระยะเฉียบพลันหรือเรื้อรังใช้ช่วยอ่านรอยโรค ไม่ใช่เกณฑ์แบ่งบางส่วนกับทั้งหมด\n— จังหวะที่ตรวจพบไม่ได้เปลี่ยนการตัดสิน สิ่งที่เปลี่ยนคือรอยโรคนั้นจำกัดอยู่จุดเดียวหรือไม่",
