    "q": "ข้อใดอธิบายจุดยืนของหลักฮาลาลต่อการทำให้สัตว์สลบก่อนเชือดได้ถูกต้อง",
    "options": [
      "บังคับให้ทำสลบด้วยไฟฟ้าทุกชนิดสัตว์ก่อนเชือด เพื่อให้สอดคล้องกับหลักสวัสดิภาพสัตว์",
      "อนุญาตให้ใช้แก๊สคาร์บอนไดออกไซด์กับโคและแพะ แต่ห้ามใช้ไฟฟ้ากับสัตว์ปีกทุกกรณี",
      "ห้ามทำให้สลบทุกกรณีทุกชนิดสัตว์ เพราะการทำสลบทำให้เลือดค้างอยู่ในซากมากเกินไป",
      "โดยหลักไม่ทำให้สลบ แต่สัตว์ปีกอาจอนุโลมให้ใช้ไฟฟ้าได้ ขึ้นกับความเข้มของการรับรอง"
    ],
    "answer": 3,
    "explain": "หลักฮาลาลกำหนดให้สัตว์มีชีวิตอยู่ ณ เวลาที่เชือด โดยปกติจึงไม่ทำให้สลบก่อน แต่มีการอนุโลมตามชนิดสัตว์และตามความเข้มของการรับรอง กรณีสัตว์ปีกอาจอนุโลมให้ทำสลบด้วยไฟฟ้าได้ ขณะที่โคอาจต้องเชือดสดโดยไม่ทำสลบ\n\n❌ ทำไมข้ออื่นผิด\n— ไม่มีข้อบังคับให้ทำสลบทุกชนิดสัตว์ เพราะการทำสลบเป็นสิ่งที่หลักฮาลาลเลี่ยงอยู่แล้ว\n— การใช้แก๊สไม่ได้อยู่ในกลุ่มที่อนุโลม และไฟฟ้ากับสัตว์ปีกคือกรณีที่อนุโลมได้ จึงกลับด้านกับความจริง\n— การห้ามทุกกรณีเข้มเกินกว่าที่มาตรฐานกำหนด และเหตุผลเรื่องเลือดค้างไม่ใช่เกณฑ์ที่ใช้ตัดสินเรื่องนี้",
