      "ออกโดยกรมปศุสัตว์ และรับรองว่าเนื้อสัตว์นั้นผ่านการตรวจซากหลังฆ่าเรียบร้อยแล้ว",
      "ออกโดยสำนักงานคณะกรรมการกลางอิสลามแห่งประเทศไทย และไม่ได้บ่งชี้คุณค่าทางโภชนาการ",
