    "explain": "เครื่องหมายฮาลาลออกโดยสำนักงานคณะกรรมการกลางอิสลามแห่งประเทศไทย มีรหัสกำกับและมีทั้งภาษาไทยและภาษาอังกฤษ ความหมายคือผลิตตามศาสนบัญญัติอิสลาม ชาวมุสลิมจึงบริโภคได้ ไม่ได้แปลว่าอาหารนั้นมีคุณค่าทางโภชนาการสูงกว่าหรือดีต่อสุขภาพมากกว่าอาหารชนิดอื่น\n\n❌ ทำไมข้ออื่นผิด\n— ตราของกรมปศุสัตว์บนเนื้อสัตว์สดหมายถึงผ่านการรับรองให้จำหน่ายจากโรงฆ่าที่มีใบอนุญาต เป็นคนละตรากับฮาลาล\n— มกอช. เป็นผู้ออกมาตรฐานอาหารฮาลาล แต่ไม่ใช่ผู้ออกเครื่องหมายบนสินค้า และมาตรฐานนี้ไม่ได้รับรองเรื่องสารตกค้าง\n— กรมอนามัยดูแลด้านสุขลักษณะและเกณฑ์น้ำบริโภค ไม่ได้ออกเครื่องหมายฮาลาล",
