    "answer": 0,
    "explain": "การขออนุญาตโรงฆ่าสัตว์เป็นใบหนึ่ง โดยการฆ่ากับการชำแหละตัดแต่งขอรวมเป็นใบเดียวกันได้ แต่ถ้ามีการแปรรูปต้องขอใบอนุญาตแยกอีกฉบับ เพราะนิยามการขนส่งเนื้อสัตว์แยกโรงฆ่า สถานที่ชำแหละตัดแต่ง และที่จำหน่ายออกจากกันอยู่แล้ว\n\n❌ ทำไมข้ออื่นผิด\n— ใบเดียวครอบคลุมทั้งสามกิจกรรมไม่ได้ เพราะการแปรรูปอยู่คนละใบ\n— ไม่ต้องแยกทั้งสามใบ เพราะการฆ่ากับการชำแหละตัดแต่งรวมกันได้\n— การชำแหละตัดแต่งและการแปรรูปไม่ได้ใช้เพียงการแจ้ง แต่ต้องมีใบอนุญาต",
