    "q": "ประเทศไทยห้ามใช้แลคโตพามีนในสุกรและไม่รับเนื้อสุกรจากประเทศที่ใช้สารนี้ ทั้งที่ประเทศผู้ส่งออกประเมินแล้วว่าปลอดภัย เหตุผลของความต่างนี้คือข้อใด",
    "options": [
      "เพราะประเทศผู้ส่งออกยังไม่ได้กำหนดค่า MRL ของสารกลุ่มนี้ไว้ในกฎหมายของตนเอง",
      "เพราะสารกลุ่มนี้สลายตัวช้าลงในสภาพอากาศร้อนชื้น จึงตกค้างในเนื้อสุกรนานกว่าเดิม",
      "เพราะ Codex ยังไม่เคยกำหนดมาตรฐานของสารกลุ่มนี้ไว้ ประเทศไทยจึงต้องห้ามไว้ก่อน",
      "เพราะการประเมินความเสี่ยงของเขาใช้ข้อมูลที่ไม่ได้รวมการตกค้างในเครื่องใน ซึ่งคนเอเชียบริโภค"
    ],
    "answer": 3,
    "explain": "แก่นของมาตรการ SPS คือฐานข้อมูลที่ใช้ประเมินต้องตรงกับพฤติกรรมการบริโภคของประเทศนั้น การประเมินของประเทศผู้ส่งออกใช้เอกสารที่ไม่ได้ครอบคลุมการตกค้างในเครื่องใน ขณะที่ผู้บริโภคในเอเชียกินเครื่องใน ผลการประเมินจึงใช้กับเราไม่ได้ มาตรการ SPS จึงไม่ได้แปลว่าสารนั้นอันตรายเสมอไป\n\n❌ ทำไมข้ออื่นผิด\n— ประเทศผู้ส่งออกกำหนดค่า MRL และมีการประเมินความเสี่ยงไว้แล้ว จึงยืนยันว่าใช้ตามฉลากแล้วปลอดภัย\n— ไม่มีการอ้างเรื่องสภาพอากาศกับการสลายตัวของสารกลุ่มนี้เป็นเหตุผลของมาตรการ\n— การที่ Codex ยังไม่กำหนดค่าไม่ใช่เหตุผลในกรณีนี้ และประเทศสมาชิกกำหนดเข้มกว่า Codex ได้อยู่แล้วหากมีหลักฐานรองรับ",
    "source": "QvEF0KAC1zI [15:39]",
