    "explain": "มาตรฐานทั่วไปเป็นแบบสมัครใจ ผู้ผลิตยื่นขอให้มาตรวจเองเพื่อให้ได้เครื่องหมาย Q ไปใช้ส่งเสริมการขาย จึงออกเป็นประกาศกำหนด ส่วนมาตรฐานบังคับใช้กับเรื่องที่สำคัญต่อความปลอดภัยของผู้บริโภค จึงออกเป็นกฎกระทรวงและมีผลบังคับกับทุกรายที่อยู่ในขอบข่าย\n\n❌ ทำไมข้ออื่นผิด\n— ไม่มีมาตรฐานสินค้าเกษตรฉบับใดที่ออกเป็นพระราชบัญญัติ เพราะ พ.ร.บ. มาตรฐานสินค้าเกษตรเป็นกฎหมายแม่อยู่แล้ว\n— ระเบียบกรมไม่ใช่รูปแบบที่ใช้ออกมาตรฐานสินค้าเกษตร\n— ทั้งสองแบบไม่ได้ออกในรูปแบบเดียวกัน เพราะการบังคับต้องอาศัยกฎกระทรวงเป็นฐาน",
