    "explain": "ผู้กำหนดและทวนสอบมาตรฐานคือ มกอช. แต่ผู้ลงตรวจคือกรมที่ดูแลสินค้านั้นโดยตรง ฟาร์มไก่ไข่ตาม มกษ. 6909-2562 ตรวจโดยกรมปศุสัตว์ เช่นเดียวกับปางช้างตาม มกษ. 6413-2563 และศูนย์รวบรวมน้ำนมดิบตาม มกษ. 6401-2558 ส่วนฟาร์มลูกกุ้งขาวแวนนาไมตาม มกษ. 7432-2558 ตรวจโดยกรมประมง\n\n❌ ทำไมข้ออื่นผิด\n— ลูกกุ้งขาวแวนนาไมเป็นสัตว์น้ำ ผู้ตรวจจึงเป็นกรมประมง ไม่ใช่กรมปศุสัตว์\n— ปางช้างเป็นสัตว์บก ผู้ตรวจคือกรมปศุสัตว์ ไม่ใช่กรมประมง\n— ศูนย์รวบรวมน้ำนมดิบอยู่ในสายปศุสัตว์ ไม่ใช่กรมวิชาการเกษตรซึ่งดูแลด้านพืช",
