    "q": "ผู้เลี้ยงช้างรายหนึ่งมีช้างเพียงเชือกเดียวและเปิดให้นักท่องเที่ยวถ่ายรูปโดยเก็บค่าบริการ กรณีนี้เข้าข่ายมาตรฐานบังคับปางช้างหรือไม่",
