    "explain": "ปางช้างใช้เกณฑ์คนละแกนกับมาตรฐานบังคับด้านอาหาร เพราะไม่ใช่เรื่องความปลอดภัยอาหาร แต่เป็นเรื่องนันทนาการและสวัสดิภาพของคนและช้าง ขอบข่ายจึงวัดจากการหารายได้ ถ้าเลี้ยงแม้เชือกเดียวแล้วเข้าเงื่อนไขข้อใดข้อหนึ่ง คือนำมาซึ่งการหารายได้ มีการถ่ายทอดสดที่บ่งชี้ที่อยู่ของช้างได้ หรือมีนิติบุคคลดูแลสถานที่ ก็ต้องปฏิบัติตาม\n\n❌ ทำไมข้ออื่นผิด\n— ไม่มีเกณฑ์จำนวนเชือกขั้นต่ำ ต่างจากฟาร์มไก่ไข่และฟาร์มสุกรที่ใช้ขนาดการผลิตเป็นเกณฑ์\n— การเก็บค่าบริการถ่ายรูปคือการหารายได้ จึงเข้าเงื่อนไขโดยตรง\n— การมีนิติบุคคลเป็นเพียงหนึ่งในเงื่อนไข ไม่ใช่เงื่อนไขเดียวที่ทำให้เข้าข่าย",
