    "q": "มาตรฐานบังคับฟาร์มไก่ไข่ให้เวลาปรับตัวแก่ฟาร์มต่างขนาดไม่เท่ากัน ข้อใดถูกต้อง",
    "options": [
      "ฟาร์มขนาด 1,000 ถึงไม่ถึง 10,000 ตัว ได้เวลาปรับตัว 5 ปี ส่วนฟาร์มตั้งแต่ 100,000 ตัวขึ้นไปทำได้ทันที",
      "ฟาร์มขนาด 1,000 ถึงไม่ถึง 10,000 ตัว ได้เวลาปรับตัว 2 ปี ส่วนฟาร์มตั้งแต่ 100,000 ตัวขึ้นไปได้ 5 ปี",
      "ฟาร์มทุกขนาดได้เวลาปรับตัวเท่ากัน 3 ปี นับจากวันที่ประกาศลงในราชกิจจานุเบกษาแล้ว",
      "ฟาร์มขนาดใหญ่ได้เวลาปรับตัวนานกว่า เพราะต้องลงทุนปรับปรุงโรงเรือนเป็นมูลค่าสูงกว่า"
    ],
    "answer": 0,
    "explain": "มาตรฐานนี้เริ่มทำปี 59 และบังคับใช้ปี 64 โดยให้ช่วงเวลาปรับตัวต่างกันตามศักยภาพของแต่ละขนาด ฟาร์มเล็กที่เลี้ยง 1,000 ถึงไม่ถึง 10,000 ตัว ได้เวลาปรับตัว 5 ปีนับจากประกาศในราชกิจจานุเบกษา ส่วนฟาร์มตั้งแต่ 100,000 ตัวขึ้นไปทำได้ทันทีจึงไม่ต้องมีช่วงผ่อนผัน ปัจจุบันบังคับใช้ครบทุกขนาดแล้ว\n\n❌ ทำไมข้ออื่นผิด\n— การให้ฟาร์มเล็ก 2 ปีและฟาร์มใหญ่ 5 ปี สลับกับความจริง\n— ไม่ได้ให้เวลาเท่ากันทุกขนาด เพราะแต่ละขนาดมีศักยภาพในการปรับตัวต่างกัน\n— ฟาร์มขนาดใหญ่ปรับตัวได้เร็วกว่า จึงไม่ได้รับช่วงเวลาผ่อนผันที่ยาวกว่า",
