    "explain": "AFTA ทำให้อัตราภาษีศุลกากรของสินค้าที่อยู่ในข้อตกลงระหว่างประเทศสมาชิกอาเซียนเหลือศูนย์ ซึ่งเป็นการลดอุปสรรคทางภาษี ส่วนอุปสรรคที่ไม่ใช่ภาษี เช่น มาตรฐานและกฎระเบียบ ยังคงอยู่และเป็นเครื่องมือที่แต่ละประเทศใช้ปกป้องผู้ผลิตในประเทศ\n\n❌ ทำไมข้ออื่นผิด\n— การคิดอัตราเดียวที่ร้อยละ 5 ไม่ตรงกับหลักของเขตการค้าเสรี\n— การยกเว้นการตรวจเอกสารที่ด่านไม่ใช่สาระของ AFTA เพราะการตรวจที่ด่านยังมีอยู่ทั้งขาเข้าและขาออก\n— AFTA เป็นข้อตกลงระหว่างสมาชิกด้วยกัน ไม่ใช่การขึ้นภาษีกับประเทศนอกกลุ่ม",
