    "answer": 0,
    "explain": "ประกาศฉบับนี้กำหนดให้สถานประกอบการอาหารในประเทศต้องขึ้นทะเบียนเป็นผู้ได้รับอนุญาตผลิตอาหารจาก อย. ทุกรายการที่เป็นอาหารต้องได้ใบอนุญาตนี้ก่อนจึงผลิตได้ เนื้อหาข้างในว่าด้วยการผลิตที่ดีและสุขลักษณะอาหารที่ดี ซึ่ง อย. นำหลักสุขลักษณะอาหารของ Codex มาทำเป็นประกาศเทียบเคียงกัน\n\n❌ ทำไมข้ออื่นผิด\n— ค่าสารตกค้างสูงสุดอยู่ในกฎหมายและมาตรฐานคนละฉบับ และ WOAH ดูแลด้านสุขภาพสัตว์ไม่ใช่ค่าตกค้างในอาหาร\n— ฉลากโภชนาการเป็นเรื่องของ TBT แต่ไม่ใช่สาระของประกาศฉบับนี้\n— มาตรฐานฟาร์มและระบบตามสอบย้อนกลับอยู่ใต้ พ.ร.บ. มาตรฐานสินค้าเกษตร ซึ่งเป็นฝั่งกระทรวงเกษตรและสหกรณ์",
