    "explain": "คณะกรรมการอาหารแห่งชาติเป็นกลไกให้สองกระทรวงหลักทำงานร่วมกัน มีนายกรัฐมนตรีเป็นประธานหรือมอบหมายรองนายกรัฐมนตรีก็ได้ และมีฝ่ายเลขานุการสองหน่วยงาน คือ อย. ฝั่งสาธารณสุข กับ มกอช. ฝั่งเกษตร โดยมีผู้แทนจากกระทรวงอื่นและตัวแทนผู้บริโภคร่วมด้วย\n\n❌ ทำไมข้ออื่นผิด\n— รัฐมนตรีว่าการกระทรวงเกษตรและสหกรณ์เป็นประธานคณะกรรมการมาตรฐานสินค้าเกษตร ซึ่งเป็นคนละชุด\n— คณะกรรมการชุดนี้อยู่เหนือระดับกระทรวง จึงไม่ได้ให้รัฐมนตรีหรือปลัดของกระทรวงใดกระทรวงหนึ่งเป็นประธาน\n— ฝ่ายเลขานุการมีสองหน่วยงานเพื่อให้ทั้งสองฝั่งเชื่อมกันได้ ไม่ใช่หน่วยงานเดียว",
