    "explain": "ปัจจุบันอาเซียนมี 11 ประเทศ โดยติมอร์-เลสเตเข้าเป็นสมาชิกล่าสุด อาเซียนแบ่งเป็น 3 เสา คือเศรษฐกิจ การเมืองและความมั่นคง และสังคมวัฒนธรรม งานด้านสินค้าเกษตรและมาตรฐาน รวมถึงคณะทำงานด้านปศุสัตว์ ประมง และพืช อยู่ภายใต้เสาเศรษฐกิจ ส่วนเสาสังคมวัฒนธรรมมีงานด้านการเทียบเคียงคุณวุฒิวิชาชีพและงานด้านอาหารที่กระทรวงสาธารณสุขดูแล\n\n❌ ทำไมข้ออื่นผิด\n— 9, 10 และ 12 ประเทศ ไม่ตรงกับจำนวนสมาชิกปัจจุบัน\n— เสาการเมืองและความมั่นคงไม่ได้ดูแลงานมาตรฐานสินค้าเกษตร\n— เสาสังคมวัฒนธรรมเกี่ยวข้องกับงานด้านสุขภาพคนและการเทียบคุณวุฒิ ไม่ใช่การกำหนดมาตรฐานสินค้าเกษตร",
