    "explain": "เครื่องอัดเม็ดใช้ไอน้ำและความร้อนทำให้วัตถุดิบจับตัวกัน แล้วลูกกลิ้งอัดวัตถุดิบผ่านรูบนแม่พิมพ์ที่มีความร้อนจนแข็งตัว รูจึงเป็นตัวกำหนดขนาดเส้นผ่านศูนย์กลาง ส่วนเครื่องตัดที่หมุนอยู่ด้านล่างเป็นตัวกำหนดความยาว โดยปรับจากระยะเวลาการหมุนให้สัมพันธ์กับความยาวที่ต้องการ\nทำไมข้ออื่นผิด\n- หน้าที่ของรูกับใบตัดถูกสลับกัน\n- ไอน้ำและอุณหภูมิมีผลต่อการจับตัวและการสุกของวัตถุดิบ ไม่ได้กำหนดมิติของเม็ด\n- ความเร็วลูกกลิ้งและความชื้นมีผลต่อคุณภาพการอัด แต่ไม่ได้กำหนดขนาดกับความยาวโดยตรง",
