      "ไก่ เป็ด ห่าน และนกพิราบ โดยเพิ่มไก่งวงกับนกกระทาเข้ามาภายหลัง",
      "ไก่ เป็ด ห่าน และนกกระจอกเทศ โดยเพิ่มนกพิราบกับนกเขาเข้ามาภายหลัง",
      "ไก่ เป็ด ห่าน และนกกระจอกเทศ โดยเพิ่มไก่งวงกับนกกระทาเข้ามาภายหลัง",
      "ไก่ เป็ด นกกระทา และนกกระจอกเทศ โดยเพิ่มห่านกับไก่งวงเข้ามาภายหลัง"
