    "answer": 2,
    "explain": "บัญชีชนิดสัตว์ของกฎหมายฉบับนี้ ฝั่งสัตว์สี่ขาคือ โค กระบือ แพะ แกะ สุกร ส่วนฝั่งสัตว์ปีกคือ ไก่ เป็ด ห่าน และนกกระจอกเทศ ต่อมาจึงมีกฎกระทรวงประกาศเพิ่มอีกสองชนิดคือไก่งวงกับนกกระทา นิยามชุดนี้แคบกว่าคำว่าสัตว์ในกฎหมายว่าด้วยวิชาชีพการสัตวแพทย์และในกฎหมายว่าด้วยโรคระบาดสัตว์ เพราะฉบับนี้เน้นปศุสัตว์ที่ใช้เพื่อการบริโภคเป็นหลัก\nทำไมข้ออื่นผิด\n- นกพิราบไม่ได้อยู่ในบัญชีชนิดสัตว์ของกฎหมายฉบับนี้ ทั้งในตัวบทเดิมและในกฎกระทรวงที่ประกาศเพิ่ม\n- นกกระจอกเทศอยู่ในตัวบทมาตั้งแต่ต้น แต่ชนิดที่ประกาศเพิ่มภายหลังคือไก่งวงกับนกกระทา ไม่ใช่นกพิราบกับนกเขา\n- ห่านอยู่ในตัวบทมาตั้งแต่ต้น ส่วนนกกระทาเป็นชนิดที่ประกาศเพิ่มภายหลัง ข้อนี้จึงสลับตำแหน่งกันสองชนิด",
    "source": "บันทึกคาบเรียน FIQC หัวข้อการควบคุมกระบวนการฆ่า ช่วงนิยามศัพท์ในพระราชบัญญัติ",
