    "explain": "ช่องทางยื่นคำขอปัจจุบันทำได้ทั้งทางอิเล็กทรอนิกส์ผ่านระบบที่กรมจัดไว้ และยื่นด้วยตนเอง โดยในกรุงเทพมหานครยื่นที่สำนักงานปศุสัตว์พื้นที่กรุงเทพมหานคร ส่วนจังหวัดอื่นยื่นที่สำนักงานปศุสัตว์จังหวัดในท้องที่ที่โรงฆ่าสัตว์นั้นตั้งอยู่ จุดที่สับสนกันบ่อยคือผู้รับคำขอกับผู้อนุญาตไม่ใช่หน่วยเดียวกัน\nทำไมข้ออื่นผิด\n- องค์กรปกครองส่วนท้องถิ่นเป็นผู้อนุญาตสำหรับโรงฆ่าสัตว์ที่จำหน่ายเนื้อสัตว์ภายในประเทศ แต่ไม่ใช่จุดที่กำหนดให้ยื่นคำขอ\n- สำนักงานปศุสัตว์เขตทำหน้าที่ฝั่งอนุมัติผลการตรวจรับรองมาตรฐานฟาร์ม ไม่ใช่จุดรับคำขอตั้งโรงฆ่าสัตว์\n- ที่ว่าการอำเภอไม่ใช่ช่องทางที่ระบุไว้ ช่องทางที่ระบุคือสำนักงานปศุสัตว์จังหวัดหรือการยื่นทางอิเล็กทรอนิกส์",
