    "explain": "กระบวนการกำหนดมาตรฐานสินค้าเกษตรของไทยในปัจจุบันมี 9 ขั้นตอน ขั้นแรกคือการพิจารณาว่าเรื่องใดสมควรกำหนดเป็นมาตรฐาน โดยดูจากผลกระทบทางเศรษฐกิจและความคุ้มค่า จากนั้นจึงเสนอคณะกรรมการมาตรฐานสินค้าเกษตร ยกร่างเอกสารเข้าคณะกรรมการวิชาการให้พิจารณาทีละบรรทัด ทำประชาพิจารณ์ในวงที่กว้างขึ้น เข้าสู่กระบวนการปรับปรุงร่าง แล้วกลับไปให้คณะกรรมการชุดใหญ่ให้ความเห็นชอบอีกรอบ\n\n❌ ทำไมข้ออื่นผิด\n— 5 ขั้นตอนไม่ใช่จำนวนขั้นของกระบวนการนี้ และการขอการรับรอง GAP ในระดับฟาร์มก็ไล่ไว้ 6 ขั้น ตั้งแต่ผ่านการอบรมจนถึงเขตอนุมัติ จึงไม่ใช่ที่มาของเลข 5\n— 7 ขั้นตอนเป็นจำนวนที่ใช้กันมาก่อน ปัจจุบันปรับเป็น 9 ขั้นตอนแล้ว\n— 12 ขั้นตอนสูงเกินไป การเวียนให้สมาชิก WTO นับเป็นขั้นเดียวที่เพิ่มเข้ามาเฉพาะกับมาตรฐานบังคับ\n\n💡 จำว่าปัจจุบัน 9 ขั้น แล้วจำต่อว่าการเวียน WTO อย่างน้อย 180 วัน เป็นขั้นที่เพิ่มเฉพาะฝั่งบังคับ",
