    "answer": 1,
    "explain": "การย้ายสัตว์เข้ามาเลี้ยงในโรงเรือนราวปี ค.ศ. 1800 คือจุดเปลี่ยนสำคัญ เพราะเมื่อสัตว์ถูกจำกัดพื้นที่ มันเลือกกินพืชหลายชนิดเองตามธรรมชาติไม่ได้อีกต่อไป โภชนะทุกตัวที่สัตว์ต้องการจึงต้องมาจากอาหารที่คนจัดให้ทั้งหมด เรื่องอาหารที่สมดุลโภชนะจึงเปลี่ยนจากสิ่งที่ธรรมชาติจัดการให้ กลายเป็นภาระของผู้เลี้ยง และเมื่อคุมอาหารกับสภาพการเลี้ยงได้แล้ว การพัฒนาสายพันธุ์ให้ผลผลิตสูงขึ้นจึงเกิดตามมาได้\n\n❌ ทำไมข้ออื่นผิด\n— การปล่อยแทะเล็มเป็นจุดตั้งต้นเดิมของการเลี้ยงสัตว์ ยังไม่ใช่การเปลี่ยนแปลงใด\n— การจัดอาหารสมดุลโภชนะเป็นผลที่ตามมาจากการเลี้ยงในโรงเรือน ไม่ใช่ต้นเหตุ\n— การพัฒนาสายพันธุ์เป็นขั้นท้ายสุด เกิดได้ต่อเมื่อคุมอาหารและการเลี้ยงได้แล้ว\n\n💡 พอสัตว์เดินหากินเองไม่ได้ คนต้องรับหน้าที่จัดโภชนะให้ครบแทน",
